function esc(s=''){return String(s).replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]))}
function normalizeOcrText(v=''){let s=String(v);s=s.replace(/\(（/g,'（').replace(/）\)/g,'）').replace(/〔（/g,'（').replace(/〔/g,'（');s=s.replace(/（\s*）\s*[）)]/g,'（ ）').replace(/[（(]\s*（\s*）/g,'（ ）');s=s.replace(/([\u3400-\u9fff])\s+(?=[\u3400-\u9fff])/g,'$1').replace(/\s+([，。；：？！])/g,'$1');return s}
