function auditQuestionBank(){let errors=[],ids=new Set,allowed=new Set(['single','multiple','judge']),residue=/(正确答案|正确等完|正确等罕|正确到衬|正确从\s*#|\|\s*$|无估|牌斜|炸贴|翘边突(?!出)|用族|不期营|电亲|账短|周转条类|肥和|手棍|【|】)/;if(Q.length!==507)errors.push(`题目总数应为507，实际为${Q.length}`);for(const q of Q){if(!Number.isInteger(q.id)||ids.has(q.id))errors.push(`题号${q.id}重复或无效`);ids.add(q.id);if(!allowed.has(q.type))errors.push(`#${q.id}题型无效`);if(!q.stem||!Array.isArray(q.options)||!q.options.length||!Array.isArray(q.answers)||!q.answers.length)errors.push(`#${q.id}字段不完整`);if(q.type==='single'&&q.answers.length!==1)errors.push(`#${q.id}单选答案数不是1`);if(q.type==='judge'&&(q.answers.length!==1||!['对','错'].includes(q.answers[0])))errors.push(`#${q.id}判断答案异常`);if(q.answers.some(a=>!q.options.includes(a)))errors.push(`#${q.id}答案不在选项中`);if(new Set(q.options).size!==q.options.length)errors.push(`#${q.id}存在重复选项`);if(q.sourceAnswerCount!=null&&q.sourceAnswerCount!==q.answers.length)errors.push(`#${q.id}答案数与原图复核数不一致`);if([q.stem,...q.options].some(x=>residue.test(String(x))))errors.push(`#${q.id}仍含答案标记或OCR残字`);let pages=q.sourceImages||[q.sourceImage];if(!pages.length||pages.some(x=>!Number.isInteger(x)||x<1||x>111))errors.push(`#${q.id}原题页码异常`)}let locks={137:['针脚无歪斜'],142:['无翘边突出'],160:['与自己无关'],166:['锤子或撬棍'],200:['肥皂'],403:['矛盾'],434:['规定用途'],437:['不期望情况'],457:['电源上挂牌'],501:['账簿记录'],505:['周转箱类']};for(const [id,words] of Object.entries(locks)){let q=Q.find(x=>x.id===Number(id)),text=[q?.stem,...(q?.options||[])].join('');if(!q||words.some(w=>!text.includes(w)))errors.push(`#${id}复核文字锁异常`)}return errors}
