function blankCount(v=''){return (displayText(v).match(/[（(]\s*[）)]/g)||[]).length}
function fillEntry(q,level='standard'){if(!q)return null;return level==='enhanced'?(ENHANCED_FILL_BANK[q.id]||FILL_BANK[q.id]||null):(FILL_BANK[q.id]||null)}
