function auditFillBanks(){let errors=[],standardIds=Object.keys(FILL_BANK),full={...FILL_BANK,...ENHANCED_FILL_BANK};if(standardIds.length!==104)errors.push(`标准填空应为104题，实际为${standardIds.length}`);if(Object.keys(full).length!==198)errors.push(`增强填空应为198题，实际为${Object.keys(full).length}`);for(const [id,e] of Object.entries(full)){let q=Q.find(x=>x.id===Number(id)),answers=e.answers||q?.answers;if(!q)errors.push(`#${id}填空原题不存在`);if(!e.stem||!e.stem.includes('______'))errors.push(`#${id}填空题干异常`);if(!Array.isArray(answers)||!answers.length)errors.push(`#${id}填空答案缺失`);if(q?.type==='judge'&&answers?.some(x=>x==='对'||x==='错'))errors.push(`#${id}判断改填空仍使用对错答案`)}return errors}
