function rotationState(){S.examRotation=S.examRotation||{round:0,recent:[],usage:{},lastSeenRound:{}};S.examRotation.lastSeenRound=S.examRotation.lastSeenRound||{};return S.examRotation}
function duplicateKey(id){return DUPLICATE_GROUP_BY_ID[id]||`Q${id}`}
function rotationRanks(){let r=rotationState(),rounds=r.recent||[];return {r,recent10:rounds.slice(-10)}}
function learningPriority(q){let l=S.learning[q.id]||{},w=S.wrong[q.id]||{},now=Date.now(),attempts=l.attempts||0,accuracy=attempts?(l.correct||0)/attempts:0,avg=l.timedAttempts?l.totalMs/l.timedAttempts:0;return (w.wrongTotal||w.count||0)*18+(w.wrongStreak||0)*35+(l.assistedCorrect||0)*14+(l.lowConfidenceCorrect||0)*12+(avg>=30000?18:0)+(l.due&&l.due<=now?25:0)+(1-accuracy)*10}
function rankedCandidates(pool,balanced=false){let {r,recent10}=rotationRanks(),round=r.round||0;return pool.map(q=>{let used=num(r.usage[q.id],0),last=num(r.lastSeenRound[q.id],0),gap=last?round-last:999,recencyPenalty=last?Math.max(0,11-gap)*30:0,exposurePenalty=used*100,learn=balanced?learningPriority(q):0,random=Math.random();return {q,score:exposurePenalty+recencyPenalty-learn,random}}).sort((a,b)=>a.score-b.score||a.random-b.random)}
