function fillStem(q,type,level='standard'){if(type!=='fill')return displayText(q.stem);return displayText(fillEntry(q,level)?.stem||q.stem)}
function renderFillStudyAnswer(item){return `<div class="fill-study-answer"><span>正确答案</span><b>${esc(questionAnswers(item.q,'fill',item.fillLevel).join('；'))}</b><small>先根据独立题干在脑中作答，再核对答案和下方的判断依据。</small></div>`}
function renderInput(item,locked){let q=item.q;if(item.renderType==='fill'){let v=Array.isArray(item.answer)?item.answer.join('、'):(item.answer||'');return `<div class="field fill-box"><textarea ${locked?'disabled':''} placeholder="请输入答案；多答案可用顿号、逗号分隔" oninput="setAnswer(this.value)">${esc(displayText(v))}</textarea><div class="fill-hint">本题题干已经人工复核，可脱离原选择题选项独立作答。</div></div>`}let multiple=q.type==='multiple',options=item.optionOrder||q.options;return `<div class="options">${options.map((o,i)=>{let sel=multiple?Array.isArray(item.answer)&&item.answer.includes(o):item.answer===o;let cls=sel?'selected':'';if(locked){let isC=q.answers.some(a=>cleanAns(a)===cleanAns(o));if(isC)cls+=' correct';else if(sel)cls+=' wrong'}return `<button class="option ${cls}" onclick="chooseOption(${i})" ${locked?'disabled':''}><span class="letter">${String.fromCharCode(65+i)}</span><span>${esc(displayText(o))}</span></button>`}).join('')}</div>`}
function setAnswer(v){session.items[current].answer=v;if(isActiveExam())queueSaveSession();else queueSave()}
function queueSaveSession(){if(saveDebounceTimer)clearTimeout(saveDebounceTimer);saveDebounceTimer=setTimeout(()=>saveSession(),350)}
function chooseOption(i){let item=session.items[current],o=(item.optionOrder||item.q.options)[i];if(item.q.type==='multiple'){let a=Array.isArray(item.answer)?[...item.answer]:[];a=a.includes(o)?a.filter(x=>x!==o):[...a,o];item.answer=a}else item.answer=o;if(isActiveExam())saveSession();else queueSave();renderQuestion('preserve')}
function baseLearning(){return {attempts:0,correct:0,wrong:0,streak:0,totalMs:0,timedAttempts:0,assistedCorrect:0,lowConfidenceCorrect:0,totalExposure:0,regularExposure:0,fillExposure:0,lastSeenRound:0,last:0,due:0}}
