function submitExam(){if(!isActiveExam())return;let unansweredItems=session.items.map((x,i)=>({x,i})).filter(z=>z.x.answer==null||z.x.answer===''||(Array.isArray(z.x.answer)&&!z.x.answer.length)),unanswered=unansweredItems.length;if(unanswered&&session.strict){current=unansweredItems[0].i;session._activeIndex=current;saveSession();renderQuestion();toast(`还有 ${unanswered} 题未作答，已跳到第一道未答题`);return}if(unanswered&&!confirm(`还有 ${unanswered} 题未作答，确定交卷吗？`))return;flushExamTimer();session._activeSince=null;session.finished=true;stopTimerTicker();document.body.classList.remove('sheet-open');if(!session.rotationRecorded){recordExamRotation(session.items);session.rotationRecorded=true}let c=0;for(const item of session.items){item.correct=answerCorrect(item,item.answer);item.checked=true;updateLearning(item,item.correct,false);if(item.correct)c++}let score=Math.round(c/session.items.length*100),total=session.totalActiveMs||session.items.reduce((a,x)=>a+(x.timeMs||0),0),timed=session.items.filter(x=>(x.timeMs||0)>0),avg=timed.length?timed.reduce((a,x)=>a+x.timeMs,0)/timed.length:0,high=session.items.filter(x=>(x.timeMs||0)>=30000&&(!avg||(x.timeMs||0)>avg*1.5)),typeTimes={};for(const x of session.items){let t=typeName(x.renderType),z=typeTimes[t]||(typeTimes[t]={total:0,count:0});if((x.timeMs||0)>0){z.total+=x.timeMs;z.count++}}let rec={time:Date.now(),mode:session.title,count:session.items.length,correct:c,score,durationMs:Math.round(total),avgMs:Math.round(avg),highCount:high.length,highIds:high.map(x=>x.q.id),typeTimes:Object.fromEntries(Object.entries(typeTimes).map(([k,v])=>[k,v.count?Math.round(v.total/v.count):0])),questionTimes:session.items.map(x=>({id:x.q.id,type:typeName(x.renderType),ms:Math.round(x.timeMs||0),correct:!!x.correct,assisted:!!x.assistedResult,confidence:x.confidence||''})),paperId:session.paperId||makePaperId(),ids:session.items.map(x=>x.q.id),renderTypes:session.items.map(x=>x.renderType),fillLevels:session.items.map(x=>x.fillLevel||'standard'),optionOrders:session.items.map(x=>x.optionOrder||x.q.options)};let ag=S.aggregateStats||(S.aggregateStats=emptyAggregate());ag.totalExams++;ag.highestScore=Math.max(ag.highestScore||0,score);ag.recentScores=[...(ag.recentScores||[]),score].slice(-20);S.history.unshift(rec);S.history=S.history.slice(0,50);S.lastSession=null;saveStore();renderResult(c,score)}
