function allTagStats(){let map=S.aggregateStats?.byTag||{};return Object.entries(map).map(([tag,z])=>{let n=num(z.attempts,0),correct=num(z.correct,0),ms=num(z.totalMs,0),slow=num(z.slow,0);return {tag,n,correct,ms,slow,wrong:n-correct,rate:n?correct/n:0,wrongRate:n?(n-correct)/n:0,slowRate:n?slow/n:0}}).sort((a,b)=>a.rate-b.rate||b.wrongRate-a.wrongRate||b.n-a.n)}
